UPDATE resolve_auto_task SET attempts = attempts + 1, next_attempt_at = #{next}, last_reason = #{reason}, last_attempt_at = #{now},
  version = version + 1, updated_at = #{now}
WHERE market_id = #{marketId} AND status = 'PENDING' AND version = #{version}

UPDATE resolve_auto_task SET status = 'RESOLVING', attempts = attempts + 1, result_option_id = #{optionId}, next_attempt_at = #{next},
  last_reason = #{reason}, last_attempt_at = #{now}, version = version + 1, updated_at = #{now}
WHERE market_id = #{marketId} AND status = 'PENDING' AND version = #{version}

UPDATE resolve_auto_task SET status = 'MANUAL', attempts = attempts + 1, last_reason = #{reason}, last_attempt_at = #{now}, version = version + 1,
  updated_at = #{now}
WHERE market_id = #{marketId} AND status = 'PENDING' AND version = #{version}
